const mod=(n,m)=>((n%m)+m)%m;
export const ETERNITY_REBORN_V2_DEF=Object.freeze({grid:ETERNITY_REBORN_V2_GRID,materials:ETERNITY_REBORN_V2_MATERIALS,parts:PARTS,
 animate({frame=0,now=0,pose='idle',reducedMotion=false,affinity='neutral'}={}){
 if(pose==='dead') return {partStates:{hideParts:true},effects:[]};
 const ms=now>0?now:frame*100, tick=(v)=>reducedMotion?0:Math.floor(ms/v), off=(v)=>reducedMotion?0:v;
 const p={outerHalo:{frame:mod(tick(145),24)}, energyCloakLeft:{frame:mod(tick(160),12)}, energyCloakRight:{frame:mod(tick(180)+off(3),12)}, lowerTails:{frame:mod(tick(175)+off(5),12)}, blackHoleCore:{frame:mod(tick(85),24)}};
 if(CORE_VARIANTS[affinity])p.blackHoleCore.overrides=CORE_VARIANTS[affinity];
 const clocks=[tick(105),-tick(137),tick(81)];for(let j=1;j<=3;j++)for(const side of ['Rear','Front'])p[`orbit${j}${side}`]={frame:mod(clocks[j-1],24)};
 for(let j=1;j<=6;j++)p[`starCrystal${j}`]={frame:mod((j%2?1:-1)*tick(120+j*13),24)};
 return {partStates:p,effects:[]};
 }});
